<template><label class="ln-textarea-field"><span v-if="label" class="ln-textarea-field__label">{{label}}</span><textarea class="ln-textarea ln-focus-ring" :value="modelValue" :rows="rows" :placeholder="placeholder" :maxlength="maxlength" :disabled="disabled" @input="update" @keydown="$emit('keydown',$event)"/><span v-if="maxlength||hint" class="ln-textarea-field__meta"><span>{{hint}}</span><span v-if="maxlength">{{modelValue.length}} / {{maxlength}}</span></span></label></template>
<script setup lang="ts">
withDefaults(defineProps<{modelValue?:string;label?:string;placeholder?:string;rows?:number;maxlength?:number;hint?:string;disabled?:boolean}>(),{modelValue:'',rows:4});const emit=defineEmits<{(e:'update:modelValue',value:string):void;(e:'keydown',event:KeyboardEvent):void}>();function update(e:Event){emit('update:modelValue',(e.target as HTMLTextAreaElement).value)}
</script>
<style scoped lang="scss">.ln-textarea-field{display:grid;gap:6px;font-family:var(--ln-font)}.ln-textarea-field__label{color:var(--ln-text);font-size:12px;font-weight:540}.ln-textarea{width:100%;min-height:84px;padding:9px 10px;resize:vertical;border:1px solid var(--ln-border-strong);border-radius:var(--ln-radius-md);outline:0;background:var(--ln-surface);color:var(--ln-text);font:13px/1.55 var(--ln-font);transition:border var(--ln-fast),box-shadow var(--ln-fast);&:focus{border-color:rgba(94,106,210,.62);box-shadow:0 0 0 2px var(--ln-accent-soft)}&::placeholder{color:var(--ln-text-tertiary)}}.ln-textarea-field__meta{display:flex;justify-content:space-between;color:var(--ln-text-tertiary);font-size:10px}</style>
